using System;using System.IO;using System.Linq;using System.Collections;using UnityEngine;using UnityEngine.UI;
public static class NWBoundary {
 static NewWeaponCombat n;static CombatEnemy e;static int releases;static string root;static GearType type;
 static void Trace(NewWeaponCombat.Trace t){if(t.stage=="release")releases++;File.AppendAllText(root+"/boundary-"+type+".jsonl",JsonUtility.ToJson(new Entry{stage=t.stage,a=t.a,b=t.b,before=t.before,after=t.after,time=t.time})+"\n");}[Serializable]class Entry{public string stage;public Vector3 a,b;public float before,after,time;}
 static IEnumerator Restart(NWProbe p){var h=CP05Training.Instance.Hero;CP05Training.Instance.RequestRestart();yield return p.Wait(()=>CP05Training.Instance.Hero!=h&&!CP05Training.Instance.Restarting,6);yield return null;yield return null;}
 static IEnumerator Setup(NWProbe p){yield return p.Wait(()=>UnityEngine.Object.FindObjectsByType<Button>().Any(b=>b.name=="训练装备架"),5);var h=CP05Training.Instance.Hero;UnityEngine.Object.FindObjectsByType<Button>().Single(b=>b.name=="训练装备架").onClick.Invoke();yield return null;yield return null;var loot=UnityEngine.Object.FindObjectsByType<LootPickup>().Single(x=>x.Gear?.type==type);p.Check(type+"-boundary-pickup",loot.PickUp(h.Inventory));var c=h.GetComponent<AdventureCombat>();p.Check(type+"-boundary-equip",c.Gear.SelectMain(loot.Gear));yield return new WaitForSeconds(.3f);n=c.NewWeapons;e=CP05Training.Instance.Enemies[0];e.enabled=false;CP05Training.Instance.Enemies[1].gameObject.SetActive(false);var cc=e.GetComponent<CharacterController>();cc.enabled=false;e.transform.position=h.transform.position+Vector3.forward*1.4f;cc.enabled=true;h.transform.rotation=Quaternion.identity;PlayerInput.Focus(true);releases=0;n.Observed+=Trace;yield return null;yield return null;}
 public static IEnumerator Run(NWProbe p){root=p.Root;yield return p.Wait(()=>CP05Training.Instance?.Hero!=null,15);for(int i=0;i<NewWeaponRegistry.EnabledCount;i++){type=(GearType)(11+i);yield return Restart(p);yield return Setup(p);var h=n.Hero;var c=n.Combat;float before=e.Health.Current;p.Check(type+"-roll-cancel-start",c.UseSkill());p.Check(type+"-roll-request",h.Dodge.TryDodge(Vector3.back));yield return new WaitForSeconds(1.5f);p.Check(type+"-roll-cancel-no-damage",releases==0&&e.Health.Current==before&&!n.Busy&&c.SkillRemaining>0);
 yield return Restart(p);yield return Setup(p);h=n.Hero;c=n.Combat;var sword=c.Gear.items.First(g=>g.type==GearType.Sword&&g.InBag);p.Check(type+"-reserve",c.Gear.SelectReserve(sword));p.Check(type+"-switch-start",c.UseSkill());p.Check(type+"-switch-real",c.SwitchWeapon());yield return new WaitForSeconds(1.3f);p.Check(type+"-switch-cancels-no-refund",releases==0&&c.SkillRemaining>0&&c.Gear.Weapon==GearType.Sword);
 yield return Restart(p);yield return Setup(p);h=n.Hero;c=n.Combat;p.Check(type+"-unload-start",c.UseSkill());var old=h;yield return Restart(p);p.Check(type+"-unload-destroys-old",old==null&&UnityEngine.Object.FindObjectsByType<NewGroundShock>().Length==0&&UnityEngine.Object.FindObjectsByType<NewWeaponTrace>().Length==0);
 string rng=JsonUtility.ToJson(UnityEngine.Random.state);foreach(GearQuality quality in Enum.GetValues(typeof(GearQuality))){var item=NewWeaponRegistry.Create(type,quality,"boundary-"+type+quality);CombatSaveSystem.ValidateCurrentItem(item);p.Check(type+"-valid-quality-"+quality,item.Weapon&&item.Definition.type==type&&item.affixes.Length==(quality==GearQuality.White?0:quality<GearQuality.Gold?1:2));var clone=JsonUtility.FromJson<GearItem>(JsonUtility.ToJson(item));p.Check(type+"-serial-"+quality,clone.id==item.id&&clone.type==type&&clone.definitionId==item.definitionId&&clone.Attack==item.Attack);}p.Check(type+"-no-old-rng",rng==JsonUtility.ToJson(UnityEngine.Random.state));var wrong=NewWeaponRegistry.Create(type,GearQuality.White);wrong.definitionId="weapon_sword";bool rejected=false;try{CombatSaveSystem.ValidateCurrentItem(wrong);}catch{rejected=true;}p.Check(type+"-wrong-definition-rejected",rejected);
 // Genuine incoming enemy attacks, no life or Damage injection. Extra enemy instances form a controlled multi-enemy death scenario.
 yield return Restart(p);yield return Setup(p);h=n.Hero;c=n.Combat;var prefab=Resources.Load<GameObject>("CP05Training/Enemy");for(int k=0;k<6;k++){var obj=UnityEngine.Object.Instantiate(prefab,h.transform.position+Quaternion.Euler(0,k*60,0)*Vector3.forward*1.35f,Quaternion.identity);UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(obj,h.gameObject.scene);var enemy=obj.GetComponent<CombatEnemy>();enemy.target=h;enemy.enabled=true;}yield return p.Wait(()=>h.Health.Dead||h.Health.Current<=18&&UnityEngine.Object.FindObjectsByType<CombatEnemy>().Any(x=>x.WindingUp&&x.TelegraphRemaining<.06f),90);bool requested=false;if(!h.Health.Dead)requested=c.UseSkill();yield return p.Wait(()=>h.Health.Dead,20);yield return null;p.Check(type+"-actual-enemy-death",h.Health.Dead&&h.Health.TotalDamageTaken>0,"unchanged prefab attacks/armor; no injected damage or life overwrite");p.Check(type+"-death-cleanup",!n.Busy&&UnityEngine.Object.FindObjectsByType<NewGroundShock>().Length==0,"request before near-lethal incoming attack="+requested);}
 }
}
